#!/bin/sh
# generated by wifi-bench-tooling/bench_session.py - DO NOT EDIT
# mode=cfg80211 session=20261124T101615Z-cfg80211-0ee4b923 sequence=session-ap-base
# hard rules encoded: never write CA 0x400392F0; never write 0xCECE during
# boot; release 0x5A5A only; one frame per idea; stop on first failed gate.
set -u
SID='20261124T101615Z-cfg80211-0ee4b923'
MODE='protocol'
P=/sys/bus/pci/devices/0000:00:00.0
R0=$P/resource0
HELPER='/root/hi5622-bar0read'
BAR0_PHYS=0
RDIR=/tmp/hi5622-bench/$SID
R=$RDIR/report.txt
W=$RDIR/writes.log
EXPECTED_KERNEL='6.18.60'
PAGE_LATCHED=0
DMESG_MARK=0
RDVAL=
mkdir -p "$RDIR" || exit 11
: > "$R"
: > "$W"
trap 'cat "$R"' EXIT

say() { printf "%s\n" "$*" >> "$R"; }
wlog() { printf "%s\n" "$*" >> "$W"; }
stop() { say "STOP:$1: $2"; say "GATE-FAIL name=$1"; say "SESSION_RESULT: STOP:$1"; exit 10; }
fail() { say "FAIL:$1: $2"; say "SESSION_RESULT: FAIL:$1"; exit 11; }
section() { say ""; say "== SECTION $1"; }
w_attr() { at=$1; v=$2; s=$3; wlog "WRITE attr=$at step=$s value=$v";
  if ! printf '%s' "$v" > "$P/$at" 2>>"$R"; then stop attr-write-failed "$at($s)"; fi; }
r_attr() { at=$1; section "$at"; cat "$P/$at" >> "$R" 2>&1 || say "READ-FAIL attr=$at"; }
r_attr_as() { n=$1; at=$2; section "$n"; cat "$P/$at" >> "$R" 2>&1 || say "READ-FAIL attr=$at"; }
norm_reg() { v=$(printf '%s' "$1" | tr -d ' \t\r\n' | tr 'A-F' 'a-f');
  case "$v" in 0x*) v=${v#0x};; esac;
  [ -n "$v" ] || { printf ''; return 0; };
  while [ "${#v}" -gt 8 ]; do v=${v#?}; done;
  while [ "${#v}" -lt 8 ]; do v=0$v; done;
  printf '%s' "$v"; }
# raw BAR0 reads go through /dev/mem at the BAR0 physical base: the PCI
# sysfs resource0 file does not support read() on this kernel (the first
# live fire of 2026-11-25 got empty values from dd if=resource0).  The
# image has CONFIG_DEVMEM=y and CONFIG_STRICT_DEVMEM=n.
rd32() { lbl=$1; off=$2;
  case "$off" in
    0x*|0X*) oh=${off#0x}; oh=${oh#0X}; offd=$((0x$oh));;
    *) offd=$((off));;
  esac
  pa=$((BAR0_PHYS + offd))
  raw=$("$HELPER" "$pa" 2>>"$R")
  val=$(norm_reg "$raw")
  if [ -z "$val" ]; then
    if command -v hexdump >/dev/null 2>&1; then
      raw=$(dd if=/dev/mem bs=1 skip=$pa count=4 2>/dev/null | hexdump -v -e '1/4 "%08x"')
    else
      raw=$(dd if=/dev/mem bs=1 skip=$pa count=4 2>/dev/null | od -An -tx4 2>/dev/null)
    fi
    val=$(norm_reg "$raw")
  fi
  RDVAL=$val
  say "RD32 label=$lbl bar0=0x$(printf %x "$offd") v=0x$val"; }
norm_hex() { v=$(printf '%s' "$1" | tr -d ' \t\n' | tr 'A-F' 'a-f');
  case "$v" in 0x*) v=${v#0x};; esac; [ -n "$v" ] || { printf 0x0; return; };
  while [ "${v#0}" != "$v" ]; do v=${v#0}; done; printf '0x%s' "${v:-0}"; }
# attr/output pattern gates normalise whitespace first: a long sysfs
# line that arrives wrapped is joined back to single spaces, so a
# multi-token pattern matches whether or not the capture wrapped.
gate_attr() { n=$1; at=$2; p=$3; if tr '\n\t' '  ' < "$P/$at" 2>/dev/null | tr -s ' ' | grep -q "$p"; then say "GATE $n PASS (attr=$at)";
  else stop "$n" "pattern not found in $at: $p"; fi; }
gate_attr_absent() { n=$1; at=$2; p=$3; if tr '\n\t' '  ' < "$P/$at" 2>/dev/null | tr -s ' ' | grep -q "$p"; then
  stop "$n" "pattern unexpectedly present in $at: $p"; else say "GATE $n PASS (attr=$at absent-pattern)"; fi; }
# predicate form of gate_attr/gate_out_has for a combined PASS-or-BLOCKED
# guard (documented pending driver feature, e.g. D2 results=0): a failing
# gate whose capture matches a blocked signature is BLOCKED, not a STOP.
attr_has() { at=$1; p=$2; tr '\n\t' '  ' < "$P/$at" 2>/dev/null | tr -s ' ' | grep -q "$p"; }
out_has() { f=$1; p=$2; tr '\n\t' '  ' < "$f" 2>/dev/null | tr -s ' ' | grep -q "$p"; }
gate_grep() { f=$1; p=$2; n=$3; if tr '\n\t' '  ' < "$f" 2>/dev/null | tr -s ' ' | grep -q "$p"; then say "GATE $n PASS ($p)";
  else stop "$n" "pattern not found: $p"; fi; }
# userspace (cfg80211 mode) gate helpers: one allowlisted command per step
gate_rc() { n=$1; got=$2; want=$3; if [ "$got" = "$want" ]; then say "GATE $n PASS rc=$got";
  else stop "$n" "exit code $got, expected $want"; fi; }
gate_out_has() { n=$1; f=$2; p=$3; if tr '\n\t' '  ' < "$f" 2>/dev/null | tr -s ' ' | grep -q "$p"; then say "GATE $n PASS (shell)";
  else stop "$n" "pattern not found in shell output: $p"; fi; }
gate_out_absent() { n=$1; f=$2; p=$3; if tr '\n\t' '  ' < "$f" 2>/dev/null | tr -s ' ' | grep -q "$p"; then
  stop "$n" "pattern unexpectedly present in shell output: $p"; else say "GATE $n PASS (shell absent)"; fi; }
gate_present() { n=$1; raw=$2; if [ -n "$raw" ]; then say "GATE $n PASS raw=0x$raw (reachable)";
  else stop "$n" "empty register read (window unreachable?)"; fi; }
IW=iw
gate_num() { n=$1; raw=$2; mode=$3; wmask=$4; wval=$5; shift=$6;
  [ -n "$raw" ] || stop "$n" "empty register read";
  raw=$(printf "%s" "$raw" | tr "A-F" "a-f"); ok=0;
  if [ "$wmask" = "ffffffff" ] && [ "$shift" = "0" ]; then
    wh=$(printf "%08x" "$((wval))")
    case "$mode" in
      eq) [ "$raw" = "$wh" ] && ok=1;;
      ne) [ "$raw" != "$wh" ] && ok=1;;
      zero) [ "$raw" = "00000000" ] && ok=1;;
      nonzero) [ "$raw" != "00000000" ] && ok=1;;
      ge) [ "$((0x$raw))" -ge "$((wval))" ] && ok=1;;
      *) stop "$n" "unknown gate mode $mode";;
    esac
  else
    v=$(( (0x$raw) >> shift )); m=$(( wmask >> shift )); got=$((v & m)); want=$(( (wval >> shift) & m ))
    case "$mode" in
      eq) [ "$got" -eq "$want" ] && ok=1;;
      ne) [ "$got" -ne "$want" ] && ok=1;;
      zero) [ "$got" -eq 0 ] && ok=1;;
      nonzero) [ "$got" -ne 0 ] && ok=1;;
      ge) [ "$got" -ge "$want" ] && ok=1;;
      *) stop "$n" "unknown gate mode $mode";;
    esac
  fi
  if [ "$ok" = "1" ]; then say "GATE $n PASS raw=0x$raw mask=$wmask want=$wval";
  else stop "$n" "expectation failed: raw=0x$raw mask=$wmask want=$wval"; fi; }
dmesg_since() { f=$1; if [ "$DMESG_MARK" -gt 0 ]; then dmesg | tail -n +$((DMESG_MARK + 1)) > "$f" 2>/dev/null; fi;
  dmesg > "$f.full" 2>/dev/null || :; tail -n 600 "$f.full" > "$f" 2>/dev/null || :; }

