section readpath
RPHYS=$(awk 'NR==1{print $1}' "$P/resource" 2>/dev/null)
case "$RPHYS" in 0x*|0X*) RH=${RPHYS#0x}; RH=${RH#0X}; BAR0_PHYS=$((0x$RH));; *) BAR0_PHYS=0;; esac
