section cfg80211-preload
# module order: cfg80211 must be present before the instrument probes
if [ -d /sys/module/cfg80211 ]; then
  say "GATE cfg80211-present PASS (built-in or already loaded)"
else
  insmod "$CFG11_MODULE" 2>>"$R" || stop cfg80211-insmod "insmod cfg80211.ko failed"
  grep -q "^cfg80211 " /proc/modules || stop cfg80211-insmod "cfg80211 not in /proc/modules"
  say "GATE cfg80211-load PASS"
fi
grep -q "^cfg80211 " /proc/modules || [ -d /sys/module/cfg80211 ] || stop cfg80211-insmod "cfg80211 absent"
say "GATE module-order PASS (cfg80211 before hi5622_wifi)"
# userspace: deployed iw if the rootfs has none; libnl-tiny from /tmp
if [ -x "$CFG11_IW" ]; then IW="$CFG11_IW"
elif command -v iw >/dev/null 2>&1; then IW=$(command -v iw)
else stop tool-missing "no iw binary (deploy --iw-bin)"; fi
