section ready
H1=0; H2=0
NOW=$(date +%s); D1=$((NOW + 2))
while [ "$(date +%s)" -lt "$D1" ]; do
  if grep -q "id1_seen=1" "$P/hcc_ready" 2>/dev/null; then H1=1; break; fi
  sleep 1
done
say "READY phase=id1 seen=$H1 deadline_s=2"
if [ "$H1" != "1" ]; then stop ready-id1-timeout "no g4 id1 device_plat_ready within 2 s"; fi
NOW=$(date +%s); D2=$((NOW + 20))
while [ "$(date +%s)" -lt "$D2" ]; do
  if grep -q "id2_seen=1" "$P/hcc_ready" 2>/dev/null; then H2=1; break; fi
  sleep 1
done
say "READY phase=id2 seen=$H2 deadline_s=20"
if [ "$H2" != "1" ]; then stop ready-id2-timeout "no g4 id2 DEVICE READY within 20 s"; fi
say "GATE ready-pair PASS"
gate_attr ready-phase hcc_ready "phase=READY_TXQ_SYNC"
r_attr_as seq-ready-hcc_ready hcc_ready
r_attr_as seq-ready-hcc_events hcc_events
r_attr_as seq-ready-rd_status rd_status

section cfg80211-ready
# the wiphy is registered by a workqueue AFTER the ready handshake
WDEAD=$(($(date +%s) + 20))
WPHY=0
while [ "$(date +%s)" -lt "$WDEAD" ]; do
  if ls /sys/class/ieee80211/ >/dev/null 2>&1; then WPHY=1; break; fi
  sleep 1
done
say "WIPHY present=$WPHY deadline_s=20"
if [ "$WPHY" != "1" ]; then stop wiphy-timeout "no /sys/class/ieee80211 phy within 20 s of the ready pair"; fi
say "GATE wiphy PASS"
say "WIPHY phy=$(ls /sys/class/ieee80211/)"
r_attr_as seq-cfg80211-ready cfg80211_status
gate_attr cfg80211-registered cfg80211_status "registered=1"
say "GATE cfg80211-registered PASS"
"$IW" phy > "$RDIR/iw-phy.out" 2>&1; IRC=$?
cat "$RDIR/iw-phy.out" >> "$R" 2>/dev/null || :
say "SHELL-RC cfg-iw-phy rc=$IRC"
gate_rc cfg-iw-phy.rc "$IRC" 0
gate_out_has cfg-iw-phy.p0 "$RDIR/iw-phy.out" "Wiphy"
say "GATE cfg-iw-phy PASS"


section protocol
say "SEQUENCE name=session-ap-base sha256=ca84682874005ab824eef65ca8d4fba1e62c436c80fe29200d722bd893c35e36 steps=10"
SEQ_BLOCKED=''

section protocol-note-base
say "STEP name=note-base kind=note"
say "STEP-ABOUT Phase A base: PD4 golden boot -> strict ready pair -> cfg80211 wiphy registered (bench_session cfg80211 preamble) -> ONE ctx_create type 1 -> ONE txq_sync72 so the core is ACTIVE. This sequence deliberately creates NO VAP and fires NO AP frame: the AP-start stage is device/ap-fire.sh (iface type __ap, mode-1 VAP base via a one-channel scan, hostapd NEW_BEACON trigger, firmware readback pack), run "
say "NOTE note-base: Phase A base: PD4 golden boot -> strict ready pair -> cfg80211 wiphy registered (bench_session cfg80211 preamble) -> ONE ctx_create type 1 -> ONE txq_sync72 so the core is ACTIVE. This sequence deliberately creates NO VAP and fires NO AP frame: the AP-start stage is device/ap-fire.sh (iface type __ap, mode-1 VAP base via a one-channel scan, hostapd NEW_BEACON trigger, firmware readback pack), run "
say "GATE note-base.captured PASS"

section protocol-cfg-status
say "STEP name=cfg-status kind=attr_expect"
say "STEP-ABOUT wiphy registered after the ready handshake (the cfg80211 preamble already waits for /sys/class/ieee80211; this is the sequence-local re-gate)"
r_attr_as seq-cfg-status cfg80211_status
  gate_attr 'cfg-status.p0' 'cfg80211_status' 'registered=1'

section protocol-pre-pack
say "STEP name=pre-pack kind=read_pack"
say "STEP-ABOUT pre-create state on this fresh boot: no context (ctx4+0x190 = 0), exception mask 0, exception staging word 0"
rd32 pre-pack.pre_ctx190 0x7D45E8
RD_pre_ctx190=$RDVAL
say "READ-OFF pre-pack.pre_ctx190 0x7D45E8"
  gate_num 'pre-pack.pre_ctx190' "$RD_pre_ctx190" zero 0xFFFFFFFF 0x00000000 0
rd32 pre-pack.pre_mask0 0x6F8008
RD_pre_mask0=$RDVAL
say "READ-OFF pre-pack.pre_mask0 0x6F8008"
  gate_num 'pre-pack.pre_mask0' "$RD_pre_mask0" zero 0xFFFFFFFF 0x00000000 0
rd32 pre-pack.pre_staging0 0x6F800C
RD_pre_staging0=$RDVAL
say "READ-OFF pre-pack.pre_staging0 0x6F800C"
  gate_num 'pre-pack.pre_staging0' "$RD_pre_staging0" zero 0xFFFFFFFF 0x00000000 0

section protocol-ctx-create-t1
say "STEP name=ctx-create-t1 kind=attr_write"
say "STEP-ABOUT prerequisite 1/2: ONE context-create H2D (g0 id1 key 0x64, data[0]=type 1) - the 2026-11-26 mode-1 bench ladder had this consumed in 0 polls before the scan"
w_attr h2d_ctx_create '1' 'ctx-create-t1'
say "GATE ctx-create-t1.write PASS"
r_attr_as seq-ctx-create-t1-h2d_status h2d_status
  gate_attr 'ctx-create-t1.p0' 'h2d_status' 'ctx_created=1'

section protocol-post-create
say "STEP name=post-create kind=read_pack"
say "STEP-ABOUT the create allocated the measured ctx4 body (same PACK as C2: ctx4[0]=4, ctx4+0x10=0x00010001, ctx4+0x434=0x0100478C)"
rd32 post-create.post_ctx190 0x7D45E8
RD_post_ctx190=$RDVAL
say "READ-OFF post-create.post_ctx190 0x7D45E8"
  gate_num 'post-create.post_ctx190' "$RD_post_ctx190" nonzero 0xFFFFFFFF 0x00000000 0
rd32 post-create.post_ctx4 0x7D4458
RD_post_ctx4=$RDVAL
say "READ-OFF post-create.post_ctx4 0x7D4458"
  gate_num 'post-create.post_ctx4' "$RD_post_ctx4" eq 0xFFFFFFFF 0x00000004 0
rd32 post-create.post_ctx10 0x7D4468
RD_post_ctx10=$RDVAL
say "READ-OFF post-create.post_ctx10 0x7D4468"
  gate_num 'post-create.post_ctx10' "$RD_post_ctx10" eq 0xFFFFFFFF 0x00010001 0
rd32 post-create.post_ctx434 0x7D488C
RD_post_ctx434=$RDVAL
say "READ-OFF post-create.post_ctx434 0x7D488C"
  gate_num 'post-create.post_ctx434' "$RD_post_ctx434" eq 0xFFFFFFFF 0x0100478C 0

section protocol-txq-sync72
say "STEP name=txq-sync72 kind=attr_write"
say "STEP-ABOUT prerequisite 2/2: ONE TXQ config sync H2D (g0 id1 cmd 0xd8, 72-byte node) -> the core is ACTIVE before the provider VAP/scan sequence (vap_start_first=1)"
w_attr h2d_txq_sync72 '1' 'txq-sync72'
say "GATE txq-sync72.write PASS"
r_attr_as seq-txq-sync72-h2d_status h2d_status
  gate_attr 'txq-sync72.p0' 'h2d_status' 'txq_sent=1'

section protocol-post-txq
say "STEP name=post-txq kind=read_pack"
say "STEP-ABOUT the TXQ handler ran clean: exception mask and staging word stay 0"
rd32 post-txq.txq_mask0 0x6F8008
RD_txq_mask0=$RDVAL
say "READ-OFF post-txq.txq_mask0 0x6F8008"
  gate_num 'post-txq.txq_mask0' "$RD_txq_mask0" zero 0xFFFFFFFF 0x00000000 0
rd32 post-txq.txq_staging0 0x6F800C
RD_txq_staging0=$RDVAL
say "READ-OFF post-txq.txq_staging0 0x6F800C"
  gate_num 'post-txq.txq_staging0' "$RD_txq_staging0" zero 0xFFFFFFFF 0x00000000 0

section protocol-h2d-status
say "STEP name=h2d-status kind=attr_expect"
say "STEP-ABOUT the two base H2D frames (ctx_create type 1 + txq_sync72) were consumed; no refusal/timeout"
r_attr_as seq-h2d-status h2d_status
  gate_attr 'h2d-status.p0' 'h2d_status' 'ok=2'
  gate_attr 'h2d-status.p1' 'h2d_status' 'timeout=0'
  gate_attr 'h2d-status.p2' 'h2d_status' 'refused=0'

section protocol-ap-pre-pack
say "STEP name=ap-pre-pack kind=read_pack"
say "STEP-ABOUT hostapd-stage pre-health (the device-side stage re-reads these before its first write): PD4 page, boot state, exception mask/staging, mailbox out0/out2 all clean"
rd32 ap-pre-pack.pre_page0 0x877000
RD_pre_page0=$RDVAL
say "READ-OFF ap-pre-pack.pre_page0 0x877000"
  gate_num 'ap-pre-pack.pre_page0' "$RD_pre_page0" eq 0xFFFFFFFF 0x86807FEF 0
rd32 ap-pre-pack.pre_page4 0x877004
RD_pre_page4=$RDVAL
say "READ-OFF ap-pre-pack.pre_page4 0x877004"
  gate_num 'ap-pre-pack.pre_page4' "$RD_pre_page4" eq 0xFFFFFFFF 0x00000007 0
rd32 ap-pre-pack.pre_page8 0x877008
RD_pre_page8=$RDVAL
say "READ-OFF ap-pre-pack.pre_page8 0x877008"
  gate_num 'ap-pre-pack.pre_page8' "$RD_pre_page8" eq 0xFFFFFFFF 0x00000002 0
rd32 ap-pre-pack.pre_page_c 0x87700C
RD_pre_page_c=$RDVAL
say "READ-OFF ap-pre-pack.pre_page_c 0x87700C"
  gate_num 'ap-pre-pack.pre_page_c' "$RD_pre_page_c" eq 0xFFFFFFFF 0x0000ABCD 0
rd32 ap-pre-pack.pre_state 0x7D0B60
RD_pre_state=$RDVAL
say "READ-OFF ap-pre-pack.pre_state 0x7D0B60"
  gate_num 'ap-pre-pack.pre_state' "$RD_pre_state" eq 0xFFFFFFFF 0x00000001 0
rd32 ap-pre-pack.pre_mask 0x6F8008
RD_pre_mask=$RDVAL
say "READ-OFF ap-pre-pack.pre_mask 0x6F8008"
  gate_num 'ap-pre-pack.pre_mask' "$RD_pre_mask" zero 0xFFFFFFFF 0x00000000 0
rd32 ap-pre-pack.pre_staging 0x6F800C
RD_pre_staging=$RDVAL
say "READ-OFF ap-pre-pack.pre_staging 0x6F800C"
  gate_num 'ap-pre-pack.pre_staging' "$RD_pre_staging" zero 0xFFFFFFFF 0x00000000 0
rd32 ap-pre-pack.pre_out0 0x3F1010
RD_pre_out0=$RDVAL
say "READ-OFF ap-pre-pack.pre_out0 0x3F1010"
  gate_num 'ap-pre-pack.pre_out0' "$RD_pre_out0" zero 0xFFFFFFFF 0x00000000 0
rd32 ap-pre-pack.pre_out2 0x3F12D4
RD_pre_out2=$RDVAL
say "READ-OFF ap-pre-pack.pre_out2 0x3F12D4"
  gate_num 'ap-pre-pack.pre_out2' "$RD_pre_out2" zero 0xFFFFFFFF 0x00000000 0

section protocol-note-end
say "STEP name=note-end kind=note"
say "STEP-ABOUT Base PASS = core ACTIVE + clean packs. The host driver then runs device/ap-fire.sh (hostapd stage) and device/ap-readback.sh; phase A PASS requires the AP-stage gates (4 frames posted+consumed, no refusal, mask/staging 0, page/state golden, VAP readback evidence). Any STOP -> power-cycle, analyse offline, never re-send a frame in the same boot."
say "NOTE note-end: Base PASS = core ACTIVE + clean packs. The host driver then runs device/ap-fire.sh (hostapd stage) and device/ap-readback.sh; phase A PASS requires the AP-stage gates (4 frames posted+consumed, no refusal, mask/staging 0, page/state golden, VAP readback evidence). Any STOP -> power-cycle, analyse offline, never re-send a frame in the same boot."
say "GATE note-end.captured PASS"

say "SEQUENCE-END name=session-ap-base"

section final
r_attr_as seq-final-h2d_status h2d_status
r_attr_as seq-final-h2d_plan h2d_plan
r_attr_as seq-final-hcc_events hcc_events
r_attr_as seq-final-hcc_ready hcc_ready
r_attr_as seq-final-hcc_status hcc_status
r_attr_as seq-final-boot boot
r_attr_as seq-final-rd_status rd_status
r_attr_as seq-final-rd_catalog rd_catalog
r_attr_as seq-final-rd_decode rd_decode
r_attr_as seq-final-cfg80211_status cfg80211_status
dmesg 2>/dev/null | tail -n 400 > "$RDIR/dmesg-final.txt" 2>/dev/null || :
section dmesg
cat "$RDIR/dmesg-final.txt" >> "$R" 2>/dev/null || :
section writes
say "WRITES-DEVICE total=$(wc -l < "$W")"
say "GATE no-cece-default PASS"
if [ -n "$SEQ_BLOCKED" ]; then
  say "SESSION_RESULT: BLOCKED:$SEQ_BLOCKED"
else
  say "SESSION_RESULT: PASS"
fi
section end
say "SESSION end=$(date +%s)"
